import { Accessor, createContext, createEffect, onCleanup, useContext } from "solid-js";

import { InputEngineEvent, NavigateInputEvent } from "#core/ui/input/input-support.js";
import NavTray from "#core/ui/navigation-tray/model-navigation-tray.js";
import { GameActionName } from "#core/ui-next/services/actionButtons.js";

export class HotkeyContextProvider {
	private hotkeyHandlers = new Map<GameActionName, (() => void)[]>();
	private navTrays = new Map<GameActionName, string[]>();
	private isActive = true;

	constructor(private parentContext?: HotkeyContextProvider | undefined) {}

	public mount() {
		if (this.parentContext) {
			this.parentContext.hide();
		}

		this.show();
	}

	public cleanup() {
		this.hide();

		NavTray.clear();

		if (this.parentContext) {
			this.parentContext.refresh();
		}
	}

	public registerHotkey(eventName: GameActionName, handler: () => void) {
		//If we already have handlers for this event, put the new one on teh stack.
		const handlers = this.hotkeyHandlers.get(eventName);
		if (handlers) {
			handlers.push(handler);
			return;
		}

		this.hotkeyHandlers.set(eventName, [handler]);
	}

	public unregisterHotkey(eventName: GameActionName) {
		const handlers = this.hotkeyHandlers.get(eventName);
		if (!handlers) {
			return;
		}

		handlers.pop();
		if (handlers.length === 0) {
			this.hotkeyHandlers.delete(eventName);
		}
	}

	public registerNavtray(eventName: GameActionName, description: string) {
		const navTrayEntry = this.navTrays.get(eventName);

		if (navTrayEntry) {
			navTrayEntry.push(description);
		} else {
			this.navTrays.set(eventName, [description]);
		}

		NavTray.addOrUpdateEntry(description, eventName);
	}

	public unregisterNavtray(eventName: GameActionName) {
		const navTrayEntry = this.navTrays.get(eventName);

		if (navTrayEntry) {
			navTrayEntry.pop();

			if (navTrayEntry.length == 0) {
				this.navTrays.delete(eventName);
			}
		}

		NavTray.removeEntry(eventName);
	}

	public onInput(event: InputEngineEvent | NavigateInputEvent): boolean {
		if (!this.isActive || event.detail.status != InputActionStatuses.FINISH) {
			return false;
		}

		const handlers = this.hotkeyHandlers.get(event.detail.name as GameActionName);
		const hotkeyHandler = handlers?.[handlers.length - 1];

		if (hotkeyHandler) {
			hotkeyHandler();
			event.preventDefault();
			event.stopPropagation();
			return true;
		}

		return false;
	}

	public hide() {
		if (!this.isActive) {
			return;
		}

		this.isActive = false;

		NavTray.clear();
	}

	public show() {
		if (this.isActive) {
			return;
		}

		this.isActive = true;

		for (const [eventName, descriptions] of this.navTrays.entries()) {
			for (const description of descriptions) {
				NavTray.addOrUpdateEntry(description, eventName);
			}
		}
	}

	public refresh() {
		this.hide();
		this.show();
	}
}

export interface HotkeyIconContextProvider {
	actionName: Accessor<string | undefined>;
	disabled: Accessor<boolean | undefined>;
}

export const HotkeyContext = createContext(new HotkeyContextProvider());
export const HotkeyIconContext = createContext<HotkeyIconContextProvider>();

export function useHotkeyContext() {
	const context = useContext(HotkeyContext);

	if (!context) {
		throw new Error("Unable to resolve hotkey context");
	}

	return context;
}

export type HotkeyArgs = Accessor<[GameActionName | undefined, () => boolean, (() => void) | undefined]>;
export type NavTrayArgs = Accessor<[GameActionName | undefined, () => boolean, string | undefined]>;

export function registerHotkey(element: HTMLElement, args: HotkeyArgs) {
	const hotkeyContext = useContext(HotkeyContext);
	let registedHotkeyAction: GameActionName | undefined;

	createEffect(() => {
		const [actionName, isEnabled, hotkeyAction] = args();

		if (!actionName) {
			if (registedHotkeyAction) {
				hotkeyContext.unregisterHotkey(registedHotkeyAction);
				registedHotkeyAction = undefined;
			}
			return;
		}

		if (!element.isConnected) {
			return;
		}

		if (isEnabled()) {
			if (actionName && hotkeyAction) {
				hotkeyContext.registerHotkey(actionName, hotkeyAction);
				registedHotkeyAction = actionName;
			}
		} else if (registedHotkeyAction) {
			hotkeyContext.unregisterHotkey(registedHotkeyAction);
			registedHotkeyAction = undefined;
		}
	});

	onCleanup(() => {
		if (registedHotkeyAction) {
			hotkeyContext.unregisterHotkey(registedHotkeyAction);
			registedHotkeyAction = undefined;
		}
	});
}

export function registerNavTray(element: HTMLElement, args: NavTrayArgs) {
	const hotkeyContext = useContext(HotkeyContext);
	let registedAction: GameActionName | undefined;

	createEffect(() => {
		const [actionName, isEnabled, description] = args();
		if (!element.isConnected) {
			return;
		}

		if (isEnabled()) {
			if (actionName && description) {
				hotkeyContext.registerNavtray(actionName, description);
				registedAction = actionName;
			}
		} else if (registedAction) {
			hotkeyContext.unregisterNavtray(registedAction);
			registedAction = undefined;
		}
	});

	onCleanup(() => {
		if (registedAction) {
			hotkeyContext.unregisterNavtray(registedAction);
			registedAction = undefined;
		}
	});
}
